-- relationships kept in hd.integrations
CREATE FUNCTION authz_int."rel_audit_1_ins"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
           nullif(current_setting('authz.acting_user', true), ''), c.action, c.ot, c.oid, c.rel, c.st, c.sid, c.sr,
           nullif(current_setting('authz_ctx.reason', true), '')
    FROM (SELECT 'relate' AS action, 'workspace' AS ot, x."workspace_id"::text AS oid, 'connected' AS rel, 'integration' AS st, x."id"::text AS sid, '' AS sr FROM new_rows x WHERE true) c;
    PERFORM authz_int.changed(c.ot, array_agg(DISTINCT c.oid), 'relationship') FROM (SELECT 'relate' AS action, 'workspace' AS ot, x."workspace_id"::text AS oid, 'connected' AS rel, 'integration' AS st, x."id"::text AS sid, '' AS sr FROM new_rows x WHERE true) c GROUP BY c.ot;
  RETURN NULL;
END $f$;
-- @object trigger "authz_rel_audit_1_ins" ON "hd"."integrations"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"hd"."integrations"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_rel_audit_1_ins" AFTER INSERT ON "hd"."integrations" REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."rel_audit_1_ins"()';
  ELSE
    RAISE NOTICE '% is not a table: changes to it are not audited or fed (audit)', '"hd"."integrations"';
  END IF;
END $tr$;
CREATE FUNCTION authz_int."rel_audit_1_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
           nullif(current_setting('authz.acting_user', true), ''), c.action, c.ot, c.oid, c.rel, c.st, c.sid, c.sr,
           nullif(current_setting('authz_ctx.reason', true), '')
    FROM (SELECT 'relate' AS action, 'workspace' AS ot, x."workspace_id"::text AS oid, 'connected' AS rel, 'integration' AS st, x."id"::text AS sid, '' AS sr FROM new_rows x WHERE true) c
    WHERE NOT EXISTS (SELECT 1 FROM (SELECT 'unrelate' AS action, 'workspace' AS ot, x."workspace_id"::text AS oid, 'connected' AS rel, 'integration' AS st, x."id"::text AS sid, '' AS sr FROM old_rows x WHERE true) o WHERE (o.ot, o.oid, o.rel, o.st, o.sid) = (c.ot, c.oid, c.rel, c.st, c.sid));
    PERFORM authz_int.changed(c.ot, array_agg(DISTINCT c.oid), 'relationship') FROM (SELECT 'relate' AS action, 'workspace' AS ot, x."workspace_id"::text AS oid, 'connected' AS rel, 'integration' AS st, x."id"::text AS sid, '' AS sr FROM new_rows x WHERE true) c GROUP BY c.ot;
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
           nullif(current_setting('authz.acting_user', true), ''), c.action, c.ot, c.oid, c.rel, c.st, c.sid, c.sr,
           nullif(current_setting('authz_ctx.reason', true), '')
    FROM (SELECT 'unrelate' AS action, 'workspace' AS ot, x."workspace_id"::text AS oid, 'connected' AS rel, 'integration' AS st, x."id"::text AS sid, '' AS sr FROM old_rows x WHERE true) c
    WHERE NOT EXISTS (SELECT 1 FROM (SELECT 'relate' AS action, 'workspace' AS ot, x."workspace_id"::text AS oid, 'connected' AS rel, 'integration' AS st, x."id"::text AS sid, '' AS sr FROM new_rows x WHERE true) o WHERE (o.ot, o.oid, o.rel, o.st, o.sid) = (c.ot, c.oid, c.rel, c.st, c.sid));
    PERFORM authz_int.changed(c.ot, array_agg(DISTINCT c.oid), 'relationship') FROM (SELECT 'unrelate' AS action, 'workspace' AS ot, x."workspace_id"::text AS oid, 'connected' AS rel, 'integration' AS st, x."id"::text AS sid, '' AS sr FROM old_rows x WHERE true) c GROUP BY c.ot;
  RETURN NULL;
END $f$;
