-- relationships kept in columns of hd.users: audited when they change; the feed hears of every row
CREATE FUNCTION authz_int."user__col_audit_ins"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    PERFORM authz_int.changed('user', ARRAY(SELECT n."id"::text FROM new_rows n), 'insert');
  RETURN NULL;
END $f$;
-- @object trigger "authz_user_col_audit_ins" ON "hd"."users"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"hd"."users"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_user_col_audit_ins" AFTER INSERT ON "hd"."users" REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__col_audit_ins"()';
  ELSE
    RAISE NOTICE '% is not a table: changes to it are not audited or fed (audit)', '"hd"."users"';
  END IF;
END $tr$;
CREATE FUNCTION authz_int."user__col_audit_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    -- the rows whose key changed, or a column access may read: a relation's, or one a condition names (a
    -- column no rule reads changes no access, and isn't announced)
    PERFORM authz_int.changed('user', ARRAY(
        SELECT n."id"::text FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id"::text = n."id"::text)
        UNION SELECT o."id"::text FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id"::text = o."id"::text)
        UNION SELECT n."id"::text FROM new_rows n JOIN old_rows o ON n."id"::text = o."id"::text
        WHERE n."customer_org_id" IS DISTINCT FROM o."customer_org_id" OR n."id" IS DISTINCT FROM o."id" OR n."workspace_id" IS DISTINCT FROM o."workspace_id" OR (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(n)) e WHERE lower(e.key) = ANY (ARRAY['active', 'kind'])) IS DISTINCT FROM (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(o)) e WHERE lower(e.key) = ANY (ARRAY['active', 'kind']))), 'update');
    -- a partitioned table: the rows this update put in another partition, which the row trigger never sees
    IF (SELECT relkind FROM pg_class WHERE oid = TG_RELID) = 'p' THEN
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'user', n."id"::text, 'self', n."id"::text, jsonb_build_object('column', 'id', 'was', o."id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."id" IS DISTINCT FROM o."id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'user'
          AND a.object_id = n."id"::text AND a.relation = 'self' AND a.detail->>'column' = 'id'
          AND a.subject_id IS NOT DISTINCT FROM n."id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."id"));
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'user', n."id"::text, 'workspace', n."workspace_id"::text, jsonb_build_object('column', 'workspace_id', 'was', o."workspace_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."workspace_id" IS DISTINCT FROM o."workspace_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'user'
          AND a.object_id = n."id"::text AND a.relation = 'workspace' AND a.detail->>'column' = 'workspace_id'
          AND a.subject_id IS NOT DISTINCT FROM n."workspace_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."workspace_id"));
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'user', n."id"::text, 'org', n."customer_org_id"::text, jsonb_build_object('column', 'customer_org_id', 'was', o."customer_org_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."customer_org_id" IS DISTINCT FROM o."customer_org_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'user'
          AND a.object_id = n."id"::text AND a.relation = 'org' AND a.detail->>'column' = 'customer_org_id'
          AND a.subject_id IS NOT DISTINCT FROM n."customer_org_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."customer_org_id"));
    END IF;
  RETURN NULL;
END $f$;
