DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"hd"."users"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_user_col_audit_upd" AFTER UPDATE ON "hd"."users" REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__col_audit_upd"()';
