-- one audit row per changed relationship column (a row trigger, so it also works when the key changes)
CREATE FUNCTION authz_int."user__col_audit_row"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NEW."id" IS DISTINCT FROM OLD."id" THEN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
    VALUES (authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'user', NEW."id"::text, 'self', NEW."id"::text, jsonb_build_object('column', 'id', 'was', OLD."id"), nullif(current_setting('authz_ctx.reason', true), ''));
  END IF;
  IF NEW."workspace_id" IS DISTINCT FROM OLD."workspace_id" THEN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
    VALUES (authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'user', NEW."id"::text, 'workspace', NEW."workspace_id"::text, jsonb_build_object('column', 'workspace_id', 'was', OLD."workspace_id"), nullif(current_setting('authz_ctx.reason', true), ''));
  END IF;
  IF NEW."customer_org_id" IS DISTINCT FROM OLD."customer_org_id" THEN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
    VALUES (authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'user', NEW."id"::text, 'org', NEW."customer_org_id"::text, jsonb_build_object('column', 'customer_org_id', 'was', OLD."customer_org_id"), nullif(current_setting('authz_ctx.reason', true), ''));
  END IF;
  RETURN NULL;
END $f$;
-- @object trigger "authz_user_col_audit_row" ON "hd"."users"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"hd"."users"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_user_col_audit_row" AFTER UPDATE ON "hd"."users" FOR EACH ROW WHEN (OLD."id" IS DISTINCT FROM NEW."id" OR OLD."workspace_id" IS DISTINCT FROM NEW."workspace_id" OR OLD."customer_org_id" IS DISTINCT FROM NEW."customer_org_id") EXECUTE FUNCTION authz_int."user__col_audit_row"()';
  ELSE
    RAISE NOTICE '% is not a table: changes to it are not audited or fed (audit)', '"hd"."users"';
  END IF;
END $tr$;

