  BEGIN
    EXECUTE format('CREATE OR REPLACE VIEW "hd"."users_visible" WITH (security_barrier) AS SELECT %s FROM "hd"."users" "users" WHERE %s',
                   cols, '(SELECT authz_int.scope_cmd(''hd.users'', ''select'')) AND ((coalesce("users"."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = "users"."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = "users"."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "users"."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = "users"."workspace_id"))
    AND coalesce((active), false))');
