COMMENT ON VIEW "hd"."users_visible" IS 'rowstile masked view';
REVOKE ALL ON "hd"."users_visible" FROM PUBLIC;
GRANT SELECT ON "hd"."users_visible" TO "hd_app";

-- Column privileges: masked columns are read through the masked view only. What masks took away is given
-- back first; then what this policy masks is taken away again
DO $mr$
DECLARE r record; cols text;
BEGIN
  FOR r IN SELECT * FROM authz.masked_tables LOOP
    IF to_regclass(r.tbl) IS NOT NULL AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r.role) THEN
      IF r.whole THEN
        -- (taking the table's SELECT back takes the SELECT on its other columns the mask gave instead)
        EXECUTE format('REVOKE SELECT ON %s FROM %I', r.tbl, r.role);
        EXECUTE format('GRANT SELECT ON %s TO %I', r.tbl, r.role);
      END IF;
      SELECT string_agg(format('%I', attname), ', ') INTO cols FROM pg_attribute
      WHERE attrelid = r.tbl::regclass AND attnum > 0 AND NOT attisdropped AND attname = ANY (r.cols);
      IF cols IS NOT NULL THEN EXECUTE format('GRANT SELECT (%s) ON %s TO %I', cols, r.tbl, r.role); END IF;
    END IF;
    DELETE FROM authz.masked_tables WHERE tbl = r.tbl AND role = r.role;
  END LOOP;
END $mr$;
DO $mc$
DECLARE cols text; whole boolean; took text[];
BEGIN
  -- hd.users: notes only through hd.users_visible
  whole := has_table_privilege('hd_app', '"hd"."users"', 'SELECT');
  -- (the SELECT of their own the masked columns have, taken away below: given back when the mask goes)
  took := ARRAY(SELECT c FROM unnest(ARRAY['notes']) c
                WHERE NOT whole AND has_column_privilege('hd_app', '"hd"."users"', c, 'SELECT'));
  IF whole THEN
    REVOKE SELECT ON "hd"."users" FROM "hd_app";
    SELECT string_agg(format('%I', attname), ', ') INTO cols FROM pg_attribute
    WHERE attrelid = '"hd"."users"'::regclass AND attnum > 0 AND NOT attisdropped
      AND attname <> ALL (ARRAY['notes']);
    IF cols IS NOT NULL THEN EXECUTE format('GRANT SELECT (%s) ON "hd"."users" TO "hd_app"', cols); END IF;
  END IF;
  IF whole OR took <> '{}' THEN
    INSERT INTO authz.masked_tables VALUES ('"hd"."users"', 'hd_app', whole, took);
  END IF;
  REVOKE SELECT ("notes") ON "hd"."users" FROM "hd_app";
  IF has_column_privilege('hd_app', '"hd"."users"', 'notes', 'SELECT') THEN
    RAISE EXCEPTION 'hd_app could still read masked columns of hd.users directly [AZ611]'
      USING HINT = 'SELECT on the table or these columns is granted to PUBLIC or to a role hd_app belongs to; revoke it, then apply again';
  END IF;
END $mc$;

CREATE TABLE authz_int.masked_columns (tbl text, col text, view text, PRIMARY KEY (tbl, col));
