-- Check a permission from app code: SELECT authz.can('file', 11, 'edit')
-- (only objects that exist; plans are cached per session)
CREATE OR REPLACE FUNCTION authz.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_allowed boolean; v_text text; v_uuid uuid;
BEGIN
  IF current_setting('authz_debug.log_decisions', true) = 'on'
     AND current_setting('authz_debug.logging', true) IS DISTINCT FROM 'on' THEN
    -- decision log (SET authz_debug.log_decisions = on; lines go to the server log), naming who acted as the
    -- audit trail does ('42', 'service:7'; none: nobody signed in)
    PERFORM set_config('authz_debug.logging', 'on', true);
    v_allowed := authz.can(p_type, p_id, p_perm);
    PERFORM set_config('authz_debug.logging', 'off', true);
    RAISE LOG 'authz decision: user=% type=% id=% perm=% -> %',
      coalesce(to_json(authz_int.actor())::text, 'none'), to_json(p_type)::text,
      to_json(p_id)::text, to_json(p_perm)::text, coalesce(v_allowed::text, 'error');
    RETURN v_allowed;
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'workspace' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")));
        WHEN 'manage_roles' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")));
        WHEN 'work_all' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
    OR (coalesce((open_queue), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id")))));
        WHEN 'work' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id")));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'impersonate' THEN RETURN EXISTS (SELECT 1 FROM "hd"."users" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))));
        WHEN 'see_notes' THEN RETURN EXISTS (SELECT 1 FROM "hd"."users" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))));
        WHEN 'org_tickets' THEN RETURN EXISTS (SELECT 1 FROM "hd"."users" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."customer_org__see_tickets" v WHERE v.id = o."customer_org_id")
    AND coalesce((active), false))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."users" o WHERE o."id" = v_uuid AND (((coalesce(o."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'integration' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'manage_keys' THEN RETURN EXISTS (SELECT 1 FROM "hd"."integrations" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."integrations" o WHERE o."id" = v_uuid AND (((coalesce(o."id" = (SELECT authz_int."integration__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'customer_org' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'see_tickets' THEN RETURN EXISTS (SELECT 1 FROM "hd"."customer_orgs" o WHERE o."id" = v_uuid AND ((coalesce((shared_tickets), false)
    AND EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."id"))));
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "hd"."customer_orgs" o WHERE o."id" = v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."customer_orgs" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id"))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'oversee' THEN RETURN EXISTS (SELECT 1 FROM "hd"."teams" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."team__lead" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."parent_id"))));
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "hd"."teams" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."team__lead" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."parent_id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."teams" o WHERE o."id" = v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'membership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."membership__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."membership__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'leadership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."leadership__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."leadership__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'support_grant' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."support_grant__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."support_grant__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'ticket' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'work' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."team_id"))))));
        WHEN 'reply' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR ((coalesce(o."requester_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = o."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."team_id"))))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR ((coalesce(o."requester_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = o."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."user__org_tickets" v WHERE v.id = o."requester_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."team_id"))))));
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")));
        WHEN 'share' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")));
        WHEN 'break_glass' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__support" v WHERE v.id = o."workspace_id")));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'comment' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."comments" o WHERE o."id" = v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."ticket__work" v WHERE v.id = o."ticket_id")
    OR (coalesce((not internal), false)
    AND EXISTS (SELECT 1 FROM authz_int."ticket__view" v WHERE v.id = o."ticket_id")))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Everything the user holds a permission on: SELECT * FROM authz.list('folder', 'edit')
-- In pages, in key order: authz.list('file', 'view', NULL, 1000), then the last id seen as p_after
CREATE OR REPLACE FUNCTION authz.list(p_type text, p_perm text, p_after text DEFAULT NULL, p_limit int DEFAULT NULL)
RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  -- a page cursor or size from a request: the caller's mistake, said plainly (the queries below would cast it)
  IF p_limit < 0 THEN
    RAISE EXCEPTION 'the page size must not be negative (got %)', p_limit
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF p_after IS NOT NULL AND NOT coalesce(pg_catalog.pg_input_is_valid(p_after,
                                            (SELECT keytype FROM authz_int.types WHERE name = p_type)), true) THEN
    RAISE EXCEPTION 'the page cursor % is not a % id', quote_literal(left(p_after, 40)), p_type
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN; END IF;
  CASE p_type || '.' || p_perm
    WHEN 'workspace.manage' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE o."id" > p_after::uuid AND EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'workspace.manage_roles' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE o."id" > p_after::uuid AND EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'workspace.work_all' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
    OR (coalesce((open_queue), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
    OR (coalesce((open_queue), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id")))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE o."id" > p_after::uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
    OR (coalesce((open_queue), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id")))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'workspace.work' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE o."id" > p_after::uuid AND EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'workspace.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE o."id" > p_after::uuid AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'user.impersonate' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE o."id" > p_after::uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'user.see_notes' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE o."id" > p_after::uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'user.org_tickets' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."customer_org__see_tickets" v WHERE v.id = o."customer_org_id")
    AND coalesce((active), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."customer_org__see_tickets" v WHERE v.id = o."customer_org_id")
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE o."id" > p_after::uuid AND (EXISTS (SELECT 1 FROM authz_int."customer_org__see_tickets" v WHERE v.id = o."customer_org_id")
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'user.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE ((coalesce(o."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE ((coalesce(o."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE o."id" > p_after::uuid AND ((coalesce(o."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'integration.manage_keys' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."integrations" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."integrations" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."integrations" o
        WHERE o."id" > p_after::uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'integration.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."integrations" o
        WHERE ((coalesce(o."id" = (SELECT authz_int."integration__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."integrations" o
        WHERE ((coalesce(o."id" = (SELECT authz_int."integration__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."integrations" o
        WHERE o."id" > p_after::uuid AND ((coalesce(o."id" = (SELECT authz_int."integration__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'customer_org.see_tickets' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."customer_orgs" o
        WHERE (coalesce((shared_tickets), false)
    AND EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."id"));
      ELSIF p_after IS NULL THEN
