CREATE FUNCTION authz_int."workspace__member__why"(p_id uuid, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT s."workspace_id" AS id FROM "hd"."users" s WHERE s."id" = (SELECT authz.uid())) THEN
    RETURN NEXT pad || 'yes  ' || 'member: a row in hd.users names you' || '';
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold workspace.member';
END $f$;

CREATE FUNCTION authz_int."workspace__agent__why"(p_id uuid, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT s."workspace_id" AS id FROM "hd"."users" s WHERE s."id" = (SELECT authz.uid()) AND coalesce((kind = 'agent'), false)) THEN
    RETURN NEXT pad || 'yes  ' || 'agent: a row in hd.users names you' || '';
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold workspace.agent';
END $f$;

CREATE FUNCTION authz_int."workspace__admin__why"(p_id uuid, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
