RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."user__impersonate");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM "hd"."users" w WHERE w."id" = p_id AND coalesce((active), false)) THEN
    RETURN NEXT pad || 'no   user ' || p_id || ' fails the type''s where {' || 'active' || '}';
    RETURN;
  END IF;
  RETURN NEXT pad || 'user.impersonate = workspace.admin';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."user__workspace__admin");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'workspace.admin';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."workspace_id" AS id FROM "hd"."users" r WHERE r."id" = p_id AND r."workspace_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the user can't see: nothing about it, or above it
      IF NOT authz_int.visible('workspace', v_t.id) THEN
        RETURN NEXT pad || '       ' || 'workspace is a workspace you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'workspace is workspace '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has admin' ELSE ', without admin' END;
      IF NOT ('workspace:admin:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."workspace__admin__why"(v_t.id::uuid, p_depth + 1 + 1, p_seen || ('workspace:admin:' || v_t.id));
      END IF;
    END LOOP;
  END;
END $f$;

